scwin.rex_rptname = ""; //Rexpert리포트 파일명 
scwin.userParam;
scwin.testDateSet;
scwin.vScrenID = "ULDINS21330.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(vSelObj),
        CORP_NM: $c.stf.getObjectValue(vSelObj)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    if (vsCoPopGb == "SCH") {
        $c.stf.setObjectValue(txb_COM_NM, scwin.arrPar[0].CORP_NM);
        $c.stf.setObjectValue(txb_ISUR_CD, scwin.arrPar[0].ISUR_CD);
    } else {
        var cbdata = "^ ," + scwin.arrPar[0].ISUR_CD + "^" + scwin.arrPar[0].CORP_NM;
        vSelObj.CBData = cbdata;
        $c.stf.setObjectValue(vSelObj, scwin.arrPar[0].ISUR_CD);
    }
};



/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(selObj) {
    if (vsCoPopGb != "SCH") {
        if (vRowCount == 0) return;
    }
    vSelObj = selObj;
    fn_GetPar = fn_GetParIsurCd;
    fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(selObj);
};


/********************************************** 
 * 함수명   : ins_search
 * 설명       : 일자별  표준코드 조회 
 ***********************************************/
scwin.ins_search = function() {
    // 코드부여일 체크
    if ($c.stf.compareFromToDate2(edt_SSTD_CD_GRNT_DD, edt_ESTD_CD_GRNT_DD) == false) {
        return false;
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS21310_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listdayGrntFeeListInquiry.return" + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}STD_CD=" + txb_pSTD_CD.getValue() +
        //"&{P}STD_CD_GRNT_FEE_PROCS_STAT_CD=" +  getObjectValue(cmb_GRNT_FEE_PROCS_STAT_CD)  +
        "&{P}SSTD_CD_GRNT_DD=" + edt_SSTD_CD_GRNT_DD.getValue() + "&{P}ESTD_CD_GRNT_DD=" + edt_ESTD_CD_GRNT_DD.getValue();
    //alert(url); 
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};
scwin.ins_fee_return = function() {
    var nRow = dts_List.getRowPosition();
    //alert('수수료환급처리'+dts_List.NameString(nRow, "COM_NM"));
    var msg = $c.stf.getMessageParam("MSG-A006", "수수료환급");
    msg += "\n";
    msg += "\n발행 기관 : " + dts_List.getCellData(nRow, "COM_NM");
    msg += "\n종  목  명 : " + dts_List.getCellData(nRow, "ISU_NM") + " (" + dts_List.getCellData(nRow, "STD_CD") + ")";
    msg += "\n환  급  금 : " + fn_SetComma(dts_List.getCellData(nRow, "STD_CD_GRNT_FEE"));
    var res = window.confirm(msg);
    if (res) {
        // 선택된 Row만 서버로 전송..
        scwin.fn_SetTransData();
        trs_Return.Action = "/PrepayInfoAction.do?method=registerFeeReturn" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Return.KeyName = "toinb_dataid4";
        trs_Return.KeyValue = "JSP(I:pInput=dts_List)";
        trs_Return.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
        trs_Return.Post();
    }
};



/**
 * 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 */
scwin.fn_SetTransData = function() {
    var nRow = dts_List.getRowPosition();
    dts_List.setCellData(nRow, "CHK", "T");
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // ISUR_APPL_ID  
    scwin.arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};
scwin.gform_onload = function() {
    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SSTD_CD_GRNT_DD.setValue($c.ut.cGetMinusDate2(vCurDate, 31)); // 1달 날짜
    edt_ESTD_CD_GRNT_DD.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    //edt_SFEE_DEPO_DD.text = cGetMinusDate2(vCurDate, 31);	// 1달 날짜
    //edt_EFEE_DEPO_DD.text = cGetToday("yyyymmdd");		// 현재날짜

    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    //showObj(ckb_11,false);
    //showObj(ckb_7,false);
    //showObj(label_19,false);
    //showObj(label_7,false);

    //ckb_ALL.checked  = true;
    //fn_allCheck();

    //ins_combo_set(dts_GRNT_FEE_PROCS_STAT_CD, vScrenID, SCREN_PROCS_TP_CD_01 ,"04028","ALL"); // 04028 - 표준코드부여수수료처리상태코드 

    //수수료환불 버튼 비활성
    btn_return.setDisabled(true);
    btn_return.src = "../img/ins/btn_fee_return_d.gif";

    //edt_SFEE_DEPO_DD.focus();

};
scwin.grd_Grid_OnHeadCheckClick = function(col, colid, bCheck) {
    fn_setCheckBox(grd_Grid, dts_List, bCheck);
};
scwin.grd_Grid_OnCheckClick = function(col, colid, bCheck) {
    fn_chkClickValid(col, colid, bCheck);
};
scwin.dts_Report_OnLoadError = function() {
    $c.stf.alert_error(dts_Report);
};
scwin.img_SSTD_CD_GRNT_DD_onclick = function() {
    popUpCalendar2(edt_SSTD_CD_GRNT_DD);
};
scwin.img_ESTD_CD_GRNT_DD_onclick = function() {
    popUpCalendar2(edt_ESTD_CD_GRNT_DD);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //수수료환불 버튼 비활성
    btn_return.setDisabled(true);
    btn_return.src = "../img/ins/btn_fee_return_d.gif";
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
