scwin.grd_Grid_OnClick = function(row, colid) {
    var statCd = dts_List.getCellData(row, "STD_CD_GRNT_FEE_PROCS_STAT_CD"); //부여수수료처리상태코드
    var del_yn = dts_List.getCellData(row, "DEL_YN"); // DEL_YN
    if (del_yn == 'Y' && statCd != '8' && statCd != '9') {
        //삭제된 && 발급취소 아닌건 && 면제가 아닌건
        btn_return.setDisabled(false);
        btn_return.src = "../img/ins/btn_fee_return.gif";
    } else {
        btn_return.setDisabled(true);
        btn_return.src = "../img/ins/btn_fee_return_d.gif";
    }
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.btn_return_onclick = function() {
    scwin.ins_fee_return();
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_pISUR_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.img_pISUR_CD_onclick = function() {
    ins_popupOpen(txb_pISUR_CD, "", "ULDINS90400", "발행기관 코드", "435", "420");
};
scwin.txb_pSTD_CD_onkeyup = function() {
