};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var title = "부여수수료환급목록";
    var xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";
    $c.data.downloadGridViewOffice(grd_Grid, title, xls_path, 8, 0);
    //grd_Grid.GridToExcel(title, "", "8");

};
scwin.trs_Return_OnFail = function() {
    alert_tr_error(trs_Return);
};
scwin.trs_Return_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.ins_search();
};
